raw:
{
  "spells": [
    {
      "id": "spell_shadow_01",
      "theory": "遮灯术把魔力引向光源周围的空气薄层，使其形成一层吸光的暗幕，只压暗可见光，不干涉燃烧所需的氧气。油灯、烛火、灯笼都可作为目标，但光源必须位于三米内且持续可见。暗幕依附在火焰或灯罩外缘，一旦光源移动过快或火焰被风吹歪，暗幕就会破裂。它不会让火焰熄灭，也不会改变灯油消耗的速度，只是让光少照出去。",
      "casting": "单手五指张开罩向光源，同时以拇指在掌心画一个向内收拢的螺旋，缓慢吐气并压低魔力输出。待光源边缘出现灰晕后，手指再向掌心收拢一次以固定暗幕。",
      "failure": "螺旋画反会使暗幕变成向外扩散的灰雾，反而让光在雾中散射，照亮更宽的区域。魔力输出过猛时，暗幕会突然收缩成黑点，随即弹开，使光源短暂刺目，周围的人会感到晃眼。",
      "counters": [
        "移走或晃动光源使暗幕脱离依附，光便恢复正常。",
        "用强风直接吹散火焰周围的暗幕薄层，遮光效果立刻减弱。"
      ],
      "socialConsequences": "河谷的乡约见证下，遮灯术常用于夜间谈话或临时避讳，但若有人用它在公共集会中偷藏灯火，会被视为扰乱秩序。城中公会对无照施术者可能收取规费，尤其是商铺为省灯油而长期遮灯。港口的货主担心有人在遮灯后调换货箱标记，因此常要求卸货区保持明亮，陌生人施术前须向管事说明用途。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时暗幕边缘抖动，光源仍会漏出细碎亮斑。",
        "环线稳定后，暗幕能均匀压暗一盏灯，不再忽明忽暗。",
        "熟练者可控制暗幕薄厚，使近处读字的光刚好够用。",
        "更高熟练度下暗幕贴合光源轮廓，仍只压暗可见光，不改变燃烧。"
      ]
    },
    {
      "id": "spell_shadow_02",
      "theory": "静影术让衣物投下的影子沿布料纤维向身体收拢，使影子变窄变淡，作用范围只限于光照边缘。魔力进入衣料后，会暂时改变影子的落点，让影子不再向外拖长，而是贴着穿着者移动。它不能隐藏身体本身，也不能让衣物消失，只是让影子轮廓更贴近身体。若衣物被强光直射或风力扯动布料，收拢的影子会重新散开。",
      "casting": "双手从衣领向下抚过衣料，同时以食指在腰侧画两道短竖线，将魔力顺着布料纹理推入。待影子边缘开始向内收拢时，双手离开衣物并保持静止片刻。",
      "failure": "竖线画得太长会使影子向内收得过紧，在脚边聚成一块不自然的黑斑。若魔力推入太快，影子会短暂反向拉长，比正常更显眼，直到魔力自行消散。",
      "counters": [
        "用强光从侧面直照，影子收拢会失效并恢复原状。",
        "拉扯或抖动衣物使魔力脱离纤维，影子随即散开。"
      ],
      "socialConsequences": "在河谷，静影术常被夜行人用来减少影子对旁人的干扰，但乡约若发现有人借收影在集市中贴近他人货摊而不留痕迹，会要求其说明意图。城市公会视其为普通衣饰法术，允许公开使用，但若用于遮挡赃物影子则另案处理。港口搬运工喜欢它，因为窄影不易绊到同伴；卫兵却会留意那些影子异常贴身的人，怀疑他们藏了未申报的货物。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时影子只收拢一半，脚边仍留明显黑边。",
        "手法稳定后，影子能均匀贴近衣物，不再出现黑斑。",
        "熟练者可控制收拢程度，使影子在强光下仍保持自然。",
        "更高熟练度下影子随动作平滑跟随，仍不隐藏身体或衣物。"
      ]
    },
    {
      "id": "spell_shadow_03",
      "theory": "暮纹术将魔力封存在墨迹中，使字迹只在暗光或背光角度下才显现。墨水本身不变色，而是墨中的魔力在光照不足时向外散出微弱暗芒，让笔画可见。纸张必须能吸墨，过于光滑的纸面会让魔力滑脱，字迹无法固定。所写的字在普通光下完全隐形，但若纸被浸湿或揉皱，墨迹中的魔力会随纸面破损而流失。",
      "casting": "以笔尖蘸墨后，在纸角画一个闭合小圈，再匀速书写内容，每写三字便将笔尖轻点纸面一次以续入魔力。写完后用指背轻压纸面，确认墨迹不粘手。",
      "failure": "小圈未闭合时，整页字迹可能只有首行显形，其余隐没。若续入魔力太急，墨迹会在暗光下泛出灰白亮边，反而比普通字更显眼，直到魔力散尽。",
      "counters": [
        "将纸张浸入清水使墨迹散开，暗光字迹便无法辨认。",
        "用强光持续照射纸面可使魔力暗芒被压制，字迹暂时不显。"
      ],
      "socialConsequences": "河谷的乡约在见证民事承诺时，允许用暮纹术写下私密条款，但若有人借隐形字迹伪造契据，会被追究欺诈。城中公会要求商业密信标明书写人，防止匿名暗字用于逃税或诬告。琥珀海岸的港务对货单上的隐形字迹尤其警惕，因为有人曾用它在提单上添加未申报货物；船主若发现暗字，须向港务说明来源，否则整批货可能被扣留待查。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时字迹在暗处忽隐忽现，需要反复调整角度。",
        "圈线稳定后，整页字迹能在暗光下均匀显现。",
        "熟练者可控制墨迹显形所需的光暗程度，减少误读。",
        "更高熟练度下字迹保存更久，仍只在暗光中显现。"
      ]
    }
  ]
}
